package com.example.order

import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.Instant
import java.util.UUID

class ProductNotFoundException(val productIds: Collection<Long>) : RuntimeException("商品不存在: $productIds")

class InsufficientStockException(val productId: Long) : RuntimeException("庫存不足: 商品 $productId")

data class OrderLine(val productId: Long, val quantity: Int)

/** [created] 為 false 代表這是同一個 Idempotency-Key 的重送,回的是先前建好的訂單。 */
data class PlacedOrder(val order: Order, val created: Boolean)

@Service
class OrderService(private val repo: OrderRepository) {

    /**
     * 整個方法是一個資料庫交易:任何一步丟例外,訂單、品項、待辦、已扣的庫存全部一起還原。
     *
     * 順序是刻意的:
     * 1. 先寫訂單列。同一個 (user, key) 的重複請求會卡在這一步等第一筆結束,碰不到庫存。
     * 2. 扣庫存放到最後。扣庫存會鎖住商品列直到交易結束,越晚鎖、鎖得越短,
     *    熱門商品每秒能排的單才越多。
     * 3. 商品依 id 由小到大扣,多筆訂單互相交叉買同幾樣商品時才不會互鎖(死結)。
     */
    @Transactional
    fun placeOrder(userId: String, idempotencyKey: String, lines: List<OrderLine>): PlacedOrder {
        val merged = lines.groupBy { it.productId }
            .mapValues { (_, same) -> same.sumOf { it.quantity } }
            .toSortedMap()

        val prices = repo.findPrices(merged.keys)
        val missing = merged.keys - prices.keys
        if (missing.isNotEmpty()) throw ProductNotFoundException(missing)

        val items = merged.map { (productId, quantity) -> OrderItem(productId, quantity, prices.getValue(productId)) }
        val total = items.sumOf { it.unitPriceCents * it.quantity }
        val orderId = UUID.randomUUID()
        val now = Instant.now()

        if (!repo.insertOrderIfAbsent(orderId, userId, idempotencyKey, total, now)) {
            return PlacedOrder(checkNotNull(repo.findOrderByKey(userId, idempotencyKey)), created = false)
        }
        repo.insertItems(orderId, items)
        repo.insertOutbox(orderId)
        items.forEach { if (!repo.deductStock(it.productId, it.quantity)) throw InsufficientStockException(it.productId) }

        return PlacedOrder(Order(orderId, userId, "PENDING", total, now, items), created = true)
    }

    @Transactional(readOnly = true)
    fun getOrder(id: UUID): Order? = repo.findOrder(id)
}
