import org.springframework.web.bind.annotation.RestControllerAdvice
import java.net.URI
import java.time.Instant
import java.util.UUID

data class OrderLineRequest(
    val productId: Long,
    @field:Min(1) @field:Max(1000) val quantity: Int,
)

data class CreateOrderRequest(
    @field:NotBlank @field:Size(max = 100) val userId: String,
    @field:Size(min = 1, max = 50) val items: List<@Valid OrderLineRequest>,
)

data class OrderResponse(
    val id: UUID,
    val userId: String,
    val status: String,
    val totalCents: Long,
    val createdAt: Instant,
    val items: List<OrderItem>,
)

private fun Order.toResponse() = OrderResponse(id, userId, status, totalCents, createdAt, items)

data class CreateProductRequest(
    @field:NotBlank val name: String,
    @field:Min(0) val priceCents: Long,
    @field:Min(0) val stock: Int,
)

@RestController
class OrderController(private val service: OrderService, private val repo: OrderRepository) {

    /** 首次建立回 201;同一個 Idempotency-Key 重送回 200 與原訂單。 */
    @PostMapping("/orders")
    fun create(
        @RequestHeader("Idempotency-Key") @Size(min = 1, max = 100) idempotencyKey: String,
        @Valid @RequestBody req: CreateOrderRequest,
    ): ResponseEntity<OrderResponse> {
        val placed = service.placeOrder(req.userId, idempotencyKey, req.items.map { OrderLine(it.productId, it.quantity) })
        val body = placed.order.toResponse()
        return if (placed.created) {
            ResponseEntity.created(URI.create("/orders/${body.id}")).body(body)
        } else {
            ResponseEntity.ok(body)
        }
    }

    @GetMapping("/orders/{id}")
    fun get(@PathVariable id: UUID): ResponseEntity<OrderResponse> =
        service.getOrder(id)?.let { ResponseEntity.ok(it.toResponse()) } ?: ResponseEntity.notFound().build()

    // 商品端點只為了能建立、查看商品與庫存;本期沒有認證,正式環境要擋在管理介面後面
    @PostMapping("/products")
    fun createProduct(@Valid @RequestBody req: CreateProductRequest): ResponseEntity<Product> {
        val id = repo.insertProduct(req.name, req.priceCents, req.stock)
        return ResponseEntity.created(URI.create("/products/$id")).body(repo.findProduct(id))
    }

    @GetMapping("/products/{id}")
    fun getProduct(@PathVariable id: Long): ResponseEntity<Product> =
        repo.findProduct(id)?.let { ResponseEntity.ok(it) } ?: ResponseEntity.notFound().build()
}

@RestControllerAdvice
class ApiExceptionHandler {

    @ExceptionHandler(InsufficientStockException::class)
    fun insufficientStock(e: InsufficientStockException): ProblemDetail =
        ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.message ?: "庫存不足")

    @ExceptionHandler(ProductNotFoundException::class)
    fun productNotFound(e: ProductNotFoundException): ProblemDetail =
        ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY, e.message ?: "商品不存在")
}
