package com.example.order

import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.UUID

/**
 * 訂單建立後的非同步處理(通知、出貨單、對外系統同步等)放在這裡。
 *
 * 約定:
 * - 至少處理一次。工作者在處理完、提交前當機,同一筆會被再處理一次,所以實作必須能重複執行。
 * - 要快。處理期間這筆工作的資料庫鎖是持有的,不要在這裡做會卡很久的呼叫。
 * - 丟例外代表失敗,會依退避時間重試,超過上限標記為 FAILED。
 */
fun interface OrderProcessor {
    fun process(orderId: UUID)
}

/** 預設實作只記一行 log;接上真正的後續流程時換掉它。 */
@Component
class LoggingOrderProcessor : OrderProcessor {
    private val log = LoggerFactory.getLogger(javaClass)

    override fun process(orderId: UUID) {
        log.info("處理訂單 {}", orderId)
    }
}
