package com.example.order

import org.slf4j.LoggerFactory
import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.jdbc.core.simple.JdbcClient
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Component
import org.springframework.transaction.support.TransactionTemplate
import java.util.UUID

@ConfigurationProperties("order.worker")
data class WorkerProperties(
    val enabled: Boolean = true,
    val pollDelayMs: Long = 200,
    val batchSize: Int = 100,
    val maxAttempts: Int = 5,
    val backoffBaseSeconds: Long = 2,
)

/**
 * 從 outbox 表領待處理的訂單、交給 [OrderProcessor]。
 *
 * 領取用 `FOR UPDATE SKIP LOCKED`:多個工作者(含多台機器)同時跑時,各自領到不同的列,
 * 被別人鎖著的直接跳過,不會等也不會重複處理。鎖持有到這一批提交為止。
 */
@Component
class OutboxWorker(
    private val jdbc: JdbcClient,
    private val tx: TransactionTemplate,
    private val processor: OrderProcessor,
    private val props: WorkerProperties,
) {
    private val log = LoggerFactory.getLogger(javaClass)

    @Scheduled(fixedDelayString = "\${order.worker.poll-delay-ms:200}")
    fun poll() {
        if (!props.enabled) return
        // 領滿一批代表可能還有積壓,接著再領,領不滿才回去睡
        while (runOnce() >= props.batchSize) Unit
    }

    /** 領一批並處理,回傳領到幾筆。測試直接呼叫這個,不靠排程。 */
    fun runOnce(): Int = tx.execute {
        val claimed = jdbc.sql(
            """
            SELECT id, order_id, attempts FROM outbox
            WHERE status = 'PENDING' AND next_attempt_at <= now()
            ORDER BY next_attempt_at
            LIMIT :n
            FOR UPDATE SKIP LOCKED
            """,
        ).param("n", props.batchSize)
            .query { rs, _ -> Triple(rs.getLong("id"), rs.getObject("order_id", UUID::class.java), rs.getInt("attempts")) }
            .list()

        claimed.forEach { (id, orderId, attempts) ->
            try {
                processor.process(orderId)
                markDone(id, orderId)
            } catch (e: Exception) {
                markAttemptFailed(id, orderId, attempts + 1, e)
            }
        }
        claimed.size
    } ?: 0

    private fun markDone(id: Long, orderId: UUID) {
        jdbc.sql("UPDATE outbox SET status = 'DONE', attempts = attempts + 1, last_error = NULL WHERE id = :id")
            .param("id", id).update()
        setOrderStatus(orderId, "PROCESSED")
    }

    private fun markAttemptFailed(id: Long, orderId: UUID, attempts: Int, e: Exception) {
        val error = (e.message ?: e.javaClass.name).take(500)
        if (attempts >= props.maxAttempts) {
            log.error("訂單 {} 處理失敗 {} 次,放棄", orderId, attempts, e)
            jdbc.sql("UPDATE outbox SET status = 'FAILED', attempts = :a, last_error = :e WHERE id = :id")
                .param("a", attempts).param("e", error).param("id", id).update()
            setOrderStatus(orderId, "FAILED")
        } else {
            // 退避:第 1 次失敗等 base 秒,之後每次加倍
            val delaySeconds = props.backoffBaseSeconds shl (attempts - 1)
            log.warn("訂單 {} 第 {} 次處理失敗,{} 秒後重試", orderId, attempts, delaySeconds, e)
            jdbc.sql(
                """
                UPDATE outbox SET attempts = :a, last_error = :e,
                       next_attempt_at = now() + make_interval(secs => :d)
                WHERE id = :id
                """,
            ).param("a", attempts).param("e", error).param("d", delaySeconds.toDouble()).param("id", id).update()
        }
    }

    private fun setOrderStatus(orderId: UUID, status: String) {
        jdbc.sql("UPDATE orders SET status = :s, updated_at = now() WHERE id = :id")
            .param("s", status).param("id", orderId).update()
    }
}
