package com.example.order

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import java.util.concurrent.Callable
import java.util.concurrent.CountDownLatch
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicInteger

class OrderConcurrencyTest : IntegrationTestBase() {

    @Autowired
    private lateinit var service: OrderService

    /** 同時放出 [n] 個任務,回傳每個任務的結果(例外也當結果)。 */
    private fun <T> race(n: Int, task: (Int) -> T): List<Result<T>> {
        val pool = Executors.newFixedThreadPool(n)
        val ready = CountDownLatch(n)
        val go = CountDownLatch(1)
        try {
            val futures = (0 until n).map { i ->
                pool.submit(Callable {
                    ready.countDown()
                    go.await()
                    runCatching { task(i) }
                })
            }
            ready.await()
            go.countDown()
            return futures.map { it.get() }
        } finally {
            pool.shutdownNow()
        }
    }

    @Test
    fun `concurrent orders never oversell`() {
        val stock = 10
        val buyers = 50
        val product = repo.insertProduct("熱門商品", 100, stock)

        val results = race(buyers) { i -> service.placeOrder("user-$i", "key-$i", listOf(OrderLine(product, 1))) }

        val succeeded = results.count { it.isSuccess }
        val soldOut = results.count { it.exceptionOrNull() is InsufficientStockException }
        // 預期值直接來自「庫存 10、50 人各買 1 件」:恰好 10 人買到、其餘 40 人被拒、沒有別種錯誤
        assertEquals(10, succeeded)
        assertEquals(40, soldOut)
        assertEquals(0, stockOf(product))
        assertEquals(10, count("orders"))
        assertEquals(10, count("outbox"))
        assertEquals(10, jdbc.queryForObject("SELECT sum(quantity) FROM order_items", Int::class.java))
    }

    @Test
    fun `insufficient stock rolls back whole order`() {
        // a 的 id 比 b 小,服務會先扣 a、再在 b 失敗;a 的庫存要被還原才算整筆回滾
        val a = repo.insertProduct("a", 100, 5)
        val b = repo.insertProduct("b", 200, 1)

        val e = assertThrows(InsufficientStockException::class.java) {
            service.placeOrder("u1", "k1", listOf(OrderLine(a, 2), OrderLine(b, 2)))
        }

        assertEquals(b, e.productId)
        assertEquals(5, stockOf(a))
        assertEquals(1, stockOf(b))
        assertEquals(0, count("orders"))
        assertEquals(0, count("order_items"))
        assertEquals(0, count("outbox"))
    }

    @Test
    fun `same idempotency key creates one order`() {
        val product = repo.insertProduct("p", 100, 10)

        val results = race(20) { service.placeOrder("u1", "same-key", listOf(OrderLine(product, 1))) }

        assertEquals(20, results.count { it.isSuccess }) // 重送不是錯誤
        val placed = results.map { it.getOrThrow() }
        assertEquals(1, placed.count { it.created })
        assertEquals(1, placed.map { it.order.id }.toSet().size)
        assertEquals(9, stockOf(product))
        assertEquals(1, count("orders"))
        assertEquals(1, count("outbox"))

        // 事後再重送一次,同樣回原訂單
        val replay = service.placeOrder("u1", "same-key", listOf(OrderLine(product, 1)))
        assertEquals(false, replay.created)
        assertEquals(placed.first().order.id, replay.order.id)
        assertEquals(9, stockOf(product))
    }

    @Test
    fun `orders touching same products in opposite order do not deadlock`() {
        val a = repo.insertProduct("a", 100, 1000)
        val b = repo.insertProduct("b", 100, 1000)
        val deadlocks = AtomicInteger()

        val results = race(40) { i ->
            // 偶數號先列 a 後列 b,奇數號相反;若服務照請求順序扣,兩邊會互相等對方的列
            val lines = if (i % 2 == 0) listOf(OrderLine(a, 1), OrderLine(b, 1)) else listOf(OrderLine(b, 1), OrderLine(a, 1))
            service.placeOrder("u$i", "k$i", lines)
        }
        results.forEach { if (it.exceptionOrNull() != null) deadlocks.incrementAndGet() }

        assertEquals(0, deadlocks.get(), results.firstNotNullOfOrNull { it.exceptionOrNull() }?.toString())
        assertEquals(960, stockOf(a))
        assertEquals(960, stockOf(b))
    }
}
