package com.example.order

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.TestConfiguration
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Primary
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CopyOnWriteArrayList
import java.util.concurrent.atomic.AtomicInteger

/** 測試用處理器:每個測試自己決定處理時要做什麼。 */
class ScriptedProcessor : OrderProcessor {
    @Volatile
    var behavior: (UUID) -> Unit = {}

    override fun process(orderId: UUID) = behavior(orderId)
}

@TestConfiguration
class ScriptedProcessorConfig {
    @Bean
    @Primary
    fun scriptedProcessor() = ScriptedProcessor()
}

@org.springframework.context.annotation.Import(ScriptedProcessorConfig::class)
class OutboxWorkerTest : IntegrationTestBase() {

    @Autowired
    private lateinit var service: OrderService

    @Autowired
    private lateinit var worker: OutboxWorker

    @Autowired
    private lateinit var processor: ScriptedProcessor

    private var product = 0L

    @BeforeEach
    fun seed() {
        processor.behavior = {}
        product = repo.insertProduct("p", 100, 1000)
    }

    private fun place(i: Int): UUID = service.placeOrder("u$i", "k$i", listOf(OrderLine(product, 1))).order.id

    private fun orderStatus(id: UUID) =
        jdbc.queryForObject("SELECT status FROM orders WHERE id = ?", String::class.java, id)

    private fun outboxRow(id: UUID) =
        jdbc.queryForMap("SELECT status, attempts, last_error, next_attempt_at > now() AS waiting FROM outbox WHERE order_id = ?", id)

    /** 把退避時間拉到現在,讓測試不用真的等。 */
    private fun makeAllDue() = jdbc.update("UPDATE outbox SET next_attempt_at = now() WHERE status = 'PENDING'")

    @Test
    fun `pending order becomes processed`() {
        val id = place(1)
        assertEquals("PENDING", orderStatus(id))
        assertEquals("PENDING", outboxRow(id)["status"])

        assertEquals(1, worker.runOnce())

        assertEquals("PROCESSED", orderStatus(id))
        assertEquals("DONE", outboxRow(id)["status"])
        assertEquals(0, worker.runOnce(), "處理完的工作不會再被領到")
    }

    @Test
    fun `failing job is retried then marked failed`() {
        val id = place(1)
        val calls = AtomicInteger()
        processor.behavior = { calls.incrementAndGet(); error("下游掛了") } // maxAttempts 預設 5

        for (attempt in 1..4) {
            assertEquals(1, worker.runOnce())
            val row = outboxRow(id)
            assertEquals("PENDING", row["status"], "第 $attempt 次失敗後還在重試")
            assertEquals(attempt, row["attempts"])
            assertEquals(true, row["waiting"], "要等退避時間,不能立刻再被領")
            assertEquals(0, worker.runOnce(), "退避中不會被領到")
            makeAllDue()
        }
        assertEquals("PENDING", orderStatus(id))

        assertEquals(1, worker.runOnce()) // 第 5 次,到上限
        assertEquals("FAILED", outboxRow(id)["status"])
        assertEquals(5, outboxRow(id)["attempts"])
        assertEquals("下游掛了", outboxRow(id)["last_error"])
        assertEquals("FAILED", orderStatus(id))
        assertEquals(5, calls.get())

        makeAllDue()
        assertEquals(0, worker.runOnce(), "放棄後不會再被領")
        assertEquals(5, calls.get())
    }

    @Test
    fun `concurrent workers never process a job twice`() {
        val ids = (1..100).map { place(it) }
        val seen = ConcurrentHashMap<UUID, AtomicInteger>()
        val threadsUsed = CopyOnWriteArrayList<String>()
        processor.behavior = {
            seen.computeIfAbsent(it) { AtomicInteger() }.incrementAndGet()
            threadsUsed += Thread.currentThread().name
            Thread.sleep(3) // 拉長持鎖時間,讓幾個工作者的批次真的重疊
        }

        val threads = (1..4).map {
            Thread { while (worker.runOnce() > 0) Unit }.apply { start() }
        }
        threads.forEach { it.join() }

        assertEquals(100, seen.size)
        assertTrue(seen.values.all { it.get() == 1 }, "有訂單被處理超過一次: ${seen.filterValues { it.get() != 1 }}")
        assertTrue(threadsUsed.toSet().size > 1, "測試情境沒成立:只有一個工作者在做事")
        assertTrue(ids.all { orderStatus(it) == "PROCESSED" })
    }
}
