    @Test
    fun `invalid requests are rejected without touching stock`() {
        val p = repo.insertProduct("p", 100, 5)
        val cases = listOf(
            "數量 0" to order("k", """{"userId":"u","items":[{"productId":$p,"quantity":0}]}""") to 400,
            "數量為負" to order("k", """{"userId":"u","items":[{"productId":$p,"quantity":-3}]}""") to 400,
            "品項為空" to order("k", """{"userId":"u","items":[]}""") to 400,
            "缺 userId" to order("k", """{"items":[{"productId":$p,"quantity":1}]}""") to 400,
            "缺 Idempotency-Key" to order(null, """{"userId":"u","items":[{"productId":$p,"quantity":1}]}""") to 400,
            "商品不存在" to order("k", """{"userId":"u","items":[{"productId":999999,"quantity":1}]}""") to 422,
            "同單混入不存在的商品" to order("k", """{"userId":"u","items":[{"productId":$p,"quantity":1},{"productId":999999,"quantity":1}]}""") to 422,
        )

        cases.forEach { (case, expected) ->
            val (name, request) = case
            assertEquals(expected, mvc.perform(request).andReturn().response.status, name)
        }

        assertEquals(5, stockOf(p))
        assertEquals(0, count("orders"))
        assertEquals(0, count("outbox"))
    }

    @Test
    fun `create replay and sold out map to 201 200 and 409`() {
        val p = repo.insertProduct("p", 250, 3)
        val body = """{"userId":"u","items":[{"productId":$p,"quantity":2}]}"""

        val location = mvc.perform(order("k1", body))
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.status").value("PENDING"))
            .andExpect(jsonPath("$.totalCents").value(500))
            .andReturn().response.getHeader("Location")!!

        mvc.perform(get(location)).andExpect(status().isOk).andExpect(jsonPath("$.items[0].quantity").value(2))

        // 同 key 重送:200、同一筆、不再扣庫存
        mvc.perform(order("k1", body)).andExpect(status().isOk).andExpect(header().doesNotExist("Location"))
        assertEquals(1, stockOf(p))

        // 新 key 要 2 件但只剩 1 件
        mvc.perform(order("k2", body)).andExpect(status().isConflict)
        assertEquals(1, stockOf(p))
        assertEquals(1, count("orders"))
    }
}
